title:
server {
    listen 80;
    server_name api.yoojoo-asset-management.xyz;
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl;
    server_name api.yoojoo-asset-management.xyz;

    ssl_certificate /etc/letsencrypt/live/api.yoojoo-asset-management.xyz/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.yoojoo-asset-management.xyz/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;

    location / {
        proxy_pass http://localhost:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

